/**
 * Security Workspace — traffic capture engine (Desktop shell, main process).
 *
 * Captures the traffic generated by the visible Browser Workspace session and
 * turns it into a bounded, searchable HTTP history + an endpoint site map. This
 * is the single source of truth that History, Site Map, and (later) the AI
 * gateway read from.
 *
 * Two producers write into one shared, bounded store:
 *   • webRequest (always-on, default): request/response metadata + request body
 *     from the browser partition's session. Cheap, reliable per-request ids,
 *     coexists with the user's DevTools. No response bodies (Chromium doesn't
 *     expose them here).
 *   • CDP / webContents.debugger (opt-in "deep mode"): response bodies + full
 *     WebSocket frames + initiator. Only one CDP client may own a page, so this
 *     yields to the user's DevTools; when DevTools is open we fall back to
 *     webRequest automatically. Only one producer records a given tab at a time.
 *
 * Bounds (never an unlimited logger): max entries, max body bytes, max total
 * memory, TTL sweep, max WS messages per connection.
 *
 * Redaction: the model-facing projection masks Authorization/Cookie/token
 * headers and password/token/secret body fields. Raw values stay only in the
 * trusted main process; the user's local panel may reveal headers, the model
 * never receives them.
 */
import type { Session, WebContents } from 'electron'
import { getScope, isInScope } from './scope'

// ── Bounds ───────────────────────────────────────────────────────────────────
const MAX_ENTRIES = 1500
const MAX_BODY_BYTES = 256 * 1024 // per captured body
const MAX_TOTAL_BYTES = 64 * 1024 * 1024 // whole store
const ENTRY_TTL_MS = 30 * 60 * 1000
const MAX_WS_MESSAGES = 500
const MAX_WS_CONNECTIONS = 100

// ── Types ──────────────────────────────────────────────────────────────────
interface Header {
  name: string
  value: string
}
interface BodyCapture {
  present: boolean
  text?: string
  base64?: boolean
  contentType?: string
  size?: number
  truncated?: boolean
  binary?: boolean
}
interface Entry {
  id: string
  producer: 'webRequest' | 'cdp'
  createdAt: number
  tabId: string | null
  webContentsId: number | null
  method: string
  url: string
  host: string
  path: string
  query: string
  resourceType: string
  status: number | null
  statusText: string
  mime: string
  requestHeaders: Header[]
  responseHeaders: Header[]
  requestBody: BodyCapture
  responseBody: BodyCapture
  requestSize: number
  responseSize: number
  startedAt: number
  endedAt: number | null
  durationMs: number | null
  fromCache: boolean
  error: string | null
  redirectChain: string[]
  protectedAuth: boolean
  inScope: boolean
}
interface WsMessage {
  ts: number
  direction: 'sent' | 'received'
  opcode: number
  text: string
  size: number
  truncated: boolean
}
interface WsConnection {
  id: string
  url: string
  host: string
  tabId: string | null
  createdAt: number
  status: 'open' | 'closed'
  requestHeaders: Header[]
  responseHeaders: Header[]
  messages: WsMessage[]
  inScope: boolean
}

// ── Store ──────────────────────────────────────────────────────────────────
const entries = new Map<string, Entry>()
const order: string[] = []
let totalBytes = 0
const wsConnections = new Map<string, WsConnection>()
const wsOrder: string[] = []

// tab correlation, populated by the renderer via IPC (tabId <-> webContentsId)
const tabByWc = new Map<number, string>()
export function mapTab(webContentsId: number, tabId: string): void {
  if (webContentsId) tabByWc.set(webContentsId, tabId)
}
export function unmapTab(webContentsId: number): void {
  tabByWc.delete(webContentsId)
}

// capture mode
let deepMode = false
const deepAttached = new Set<number>() // webContentsIds with a live CDP producer
export function setCaptureMode(opts: { deep?: boolean }): { deep: boolean } {
  if (typeof opts?.deep === 'boolean') deepMode = opts.deep
  return { deep: deepMode }
}
function deepActive(webContentsId: number | null): boolean {
  return deepMode && webContentsId !== null && deepAttached.has(webContentsId)
}

export function clearCapture(): void {
  entries.clear()
  order.length = 0
  totalBytes = 0
  wsConnections.clear()
  wsOrder.length = 0
}

// ── Redaction ────────────────────────────────────────────────────────────────
const SENSITIVE_HEADER =
  /^(authorization|proxy-authorization|cookie|set-cookie|x-api-key|x-auth-token|x-csrf-token|x-xsrf-token|api-key|authentication|x-amz-security-token)$/i
const SENSITIVE_HEADER_SUBSTR = /(token|secret|password|session|apikey|api-key)/i
const SENSITIVE_FIELD = /(pass(word)?|token|secret|otp|cvv|card|authorization|session|api[_-]?key|client[_-]?secret)/i

function headerIsSensitive(name: string): boolean {
  return SENSITIVE_HEADER.test(name) || SENSITIVE_HEADER_SUBSTR.test(name)
}
function redactHeaders(headers: Header[], reveal: boolean): Header[] {
  return headers.map((h) =>
    !reveal && headerIsSensitive(h.name) ? { name: h.name, value: '[REDACTED]' } : { ...h }
  )
}
function redactBody(body: BodyCapture, reveal: boolean): BodyCapture {
  if (!body?.present || body.binary || body.base64 || !body.text) return { ...body }
  if (reveal) return { ...body }
  return { ...body, text: maskBodyText(body.text, body.contentType) }
}
function maskBodyText(text: string, contentType?: string): string {
  const ct = (contentType || '').toLowerCase()
  try {
    if (ct.includes('json') || /^[\s{[]/.test(text)) {
      const parsed = JSON.parse(text)
      return JSON.stringify(maskJson(parsed))
    }
  } catch {
    /* not JSON; fall through */
  }
  if (ct.includes('x-www-form-urlencoded') || /^[^=&\s]+=[^=&\s]*(&|$)/.test(text)) {
    return text
      .split('&')
      .map((kv) => {
        const i = kv.indexOf('=')
        if (i < 0) return kv
        const k = kv.slice(0, i)
        return SENSITIVE_FIELD.test(decodeURIComponent(k)) ? `${k}=[REDACTED]` : kv
      })
      .join('&')
  }
  return text
}
function maskJson(node: unknown): unknown {
  if (Array.isArray(node)) return node.map(maskJson)
  if (node && typeof node === 'object') {
    const out: Record<string, unknown> = {}
    for (const [k, v] of Object.entries(node as Record<string, unknown>)) {
      out[k] = SENSITIVE_FIELD.test(k) ? '[REDACTED]' : maskJson(v)
    }
    return out
  }
  return node
}
function hasProtectedAuth(headers: Header[]): boolean {
  return headers.some((h) => /^(authorization|cookie|proxy-authorization)$/i.test(h.name))
}

// ── Helpers ──────────────────────────────────────────────────────────────────
function splitUrl(url: string): { host: string; path: string; query: string } {
  try {
    const u = new URL(url)
    return { host: u.host, path: u.pathname, query: u.search.replace(/^\?/, '') }
  } catch {
    return { host: '', path: url, query: '' }
  }
}
function approxBytes(e: Entry): number {
  let n = e.url.length + 256
  for (const h of e.requestHeaders) n += h.name.length + h.value.length
  for (const h of e.responseHeaders) n += h.name.length + h.value.length
  n += e.requestBody.text?.length || 0
  n += e.responseBody.text?.length || 0
  return n
}
function evict(): void {
  const now = Date.now()
  // TTL sweep
  for (const id of [...order]) {
    const e = entries.get(id)
    if (e && now - e.createdAt > ENTRY_TTL_MS) remove(id)
  }
  // Count + memory caps (drop oldest)
  while (order.length > MAX_ENTRIES || totalBytes > MAX_TOTAL_BYTES) {
    const oldest = order[0]
    if (!oldest) break
    remove(oldest)
  }
}
function remove(id: string): void {
  const e = entries.get(id)
  if (!e) return
  totalBytes -= approxBytes(e)
  entries.delete(id)
  const i = order.indexOf(id)
  if (i >= 0) order.splice(i, 1)
}
function put(e: Entry): void {
  if (!entries.has(e.id)) {
    order.push(e.id)
    entries.set(e.id, e)
  } else {
    totalBytes -= approxBytes(entries.get(e.id)!)
  }
  totalBytes += approxBytes(e)
  evict()
}
function newEntry(id: string, producer: Entry['producer'], url: string, method: string, wcId: number | null): Entry {
  const { host, path, query } = splitUrl(url)
  return {
    id,
    producer,
    createdAt: Date.now(),
    tabId: wcId !== null ? tabByWc.get(wcId) ?? null : null,
    webContentsId: wcId,
    method: (method || 'GET').toUpperCase(),
    url,
    host,
    path,
    query,
    resourceType: 'other',
    status: null,
    statusText: '',
    mime: '',
    requestHeaders: [],
    responseHeaders: [],
    requestBody: { present: false },
    responseBody: { present: false },
    requestSize: 0,
    responseSize: 0,
    startedAt: Date.now(),
    endedAt: null,
    durationMs: null,
    fromCache: false,
    error: null,
    redirectChain: [],
    protectedAuth: false,
    inScope: isInScope(url)
  }
}
function toHeaders(obj: Record<string, string | string[]> | undefined): Header[] {
  const out: Header[] = []
  if (!obj) return out
  for (const [name, value] of Object.entries(obj)) {
    if (Array.isArray(value)) for (const v of value) out.push({ name, value: String(v) })
    else out.push({ name, value: String(value) })
  }
  return out
}

// ── webRequest producer (always-on) ────────────────────────────────────────
/**
 * Install capture on the browser partition session. IMPORTANT: onBeforeRequest
 * also performs the existing dangerous-scheme block, so this REPLACES the
 * caller's onBeforeRequest (Electron allows one listener per event).
 */
export function installCapture(browserSession: Session): void {
  const captureOk = (details: { url?: string; webContentsId?: number }): boolean => {
    const s = getScope()
    if (s.captureInScopeOnly && !isInScope(details.url || '')) return false
    return true
  }

  browserSession.webRequest.onBeforeRequest((details, callback) => {
    // Preserve the dangerous-scheme block.
    if (/^(file|chrome|devtools|chrome-extension):/i.test(details.url || '')) {
      callback({ cancel: true })
      return
    }
    try {
      const wcId = (details as { webContentsId?: number }).webContentsId ?? null
      if (!deepActive(wcId) && captureOk(details)) {
        const e = newEntry(`wr:${details.id}`, 'webRequest', details.url || '', details.method || 'GET', wcId)
        e.resourceType = String((details as { resourceType?: string }).resourceType || 'other')
        const upload = (details as { uploadData?: Array<{ bytes?: Uint8Array }> }).uploadData
        if (Array.isArray(upload) && upload.length) {
          const bytes = upload.reduce((n, u) => n + (u.bytes?.length || 0), 0)
          e.requestSize = bytes
          const joined = Buffer.concat(upload.map((u) => Buffer.from(u.bytes || [])))
          e.requestBody = capBody(joined, undefined)
        }
        put(e)
      }
    } catch {
      /* never break navigation on a capture error */
    }
    callback({})
  })

  browserSession.webRequest.onSendHeaders((details) => {
    const e = entries.get(`wr:${details.id}`)
    if (!e) return
    e.requestHeaders = toHeaders(details.requestHeaders)
    e.protectedAuth = hasProtectedAuth(e.requestHeaders)
  })

  browserSession.webRequest.onHeadersReceived((details, callback) => {
    const e = entries.get(`wr:${details.id}`)
    if (e) {
      e.status = details.statusCode ?? e.status
      e.statusText = String((details as { statusLine?: string }).statusLine || '')
      e.responseHeaders = toHeaders(details.responseHeaders as Record<string, string[]>)
      const ct = e.responseHeaders.find((h) => /^content-type$/i.test(h.name))
      if (ct) e.mime = ct.value.split(';')[0].trim()
    }
    callback({})
  })

  browserSession.webRequest.onBeforeRedirect((details) => {
    const e = entries.get(`wr:${details.id}`)
    if (e) e.redirectChain.push(String((details as { redirectURL?: string }).redirectURL || ''))
  })

  browserSession.webRequest.onCompleted((details) => {
    const e = entries.get(`wr:${details.id}`)
    if (!e) return
    e.status = details.statusCode ?? e.status
    e.endedAt = Date.now()
    e.durationMs = e.endedAt - e.startedAt
    e.fromCache = !!(details as { fromCache?: boolean }).fromCache
    const len = e.responseHeaders.find((h) => /^content-length$/i.test(h.name))
    if (len) e.responseSize = parseInt(len.value, 10) || 0
  })

  browserSession.webRequest.onErrorOccurred((details) => {
    const e = entries.get(`wr:${details.id}`)
    if (!e) return
    e.error = String((details as { error?: string }).error || 'error')
    e.endedAt = Date.now()
    e.durationMs = e.endedAt - e.startedAt
  })
}

function capBody(buf: Buffer, contentType?: string): BodyCapture {
  const size = buf.length
  if (!size) return { present: false }
  const truncated = size > MAX_BODY_BYTES
  const slice = truncated ? buf.subarray(0, MAX_BODY_BYTES) : buf
  // crude binary sniff: NUL byte in the first 1KB
  const binary = slice.subarray(0, 1024).includes(0)
  if (binary) return { present: true, binary: true, contentType, size, truncated }
  return { present: true, text: slice.toString('utf-8'), contentType, size, truncated }
}

// ── CDP producer (deep mode) ────────────────────────────────────────────────
/**
 * Attach the CDP Network domain to a browser guest for response bodies + WS
 * frames. Called from did-attach-webview. Yields gracefully to the user's
 * DevTools (only one debugger client per page).
 */
export function attachDeep(guest: WebContents): void {
  const wcId = guest.id
  if (!deepMode) return
  const dbg = guest.debugger
  try {
    if (dbg.isAttached()) return
    dbg.attach('1.3')
  } catch {
    return // DevTools already owns it, or attach failed — webRequest covers us
  }
  deepAttached.add(wcId)
  const cdpReq = new Map<string, Entry>()

  const send = (method: string, params?: object): Promise<any> => dbg.sendCommand(method, params).catch(() => ({}))
  send('Network.enable', { maxtotal: MAX_TOTAL_BYTES, maxResource: MAX_BODY_BYTES })

  dbg.on('message', (_e, method, params: any) => {
    try {
      handleCdp(method, params)
    } catch {
      /* never throw out of a CDP handler */
    }
  })

  function handleCdp(method: string, params: any): void {
    if (method === 'Network.requestWillBeSent') {
      const url = params?.request?.url || ''
      const s = getScope()
      if (s.captureInScopeOnly && !isInScope(url)) return
      const e = newEntry(`cdp:${wcId}:${params.requestId}`, 'cdp', url, params?.request?.method || 'GET', wcId)
      e.requestHeaders = toHeaders(params?.request?.headers)
      e.protectedAuth = hasProtectedAuth(e.requestHeaders)
      e.resourceType = String(params?.type || 'other').toLowerCase()
      if (typeof params?.request?.postData === 'string') {
        e.requestBody = capBody(Buffer.from(params.request.postData, 'utf-8'), undefined)
        e.requestSize = e.requestBody.size || 0
      }
      if (params?.redirectResponse?.url) e.redirectChain.push(params.redirectResponse.url)
      cdpReq.set(params.requestId, e)
      put(e)
    } else if (method === 'Network.responseReceived') {
      const e = cdpReq.get(params.requestId)
      if (!e) return
      e.status = params?.response?.status ?? e.status
      e.statusText = String(params?.response?.statusText || '')
      e.responseHeaders = toHeaders(params?.response?.headers)
      e.mime = String(params?.response?.mimeType || e.mime)
    } else if (method === 'Network.loadingFinished') {
      const e = cdpReq.get(params.requestId)
      if (!e) return
      e.endedAt = Date.now()
      e.durationMs = e.endedAt - e.startedAt
      e.responseSize = Number(params?.encodedDataLength || e.responseSize)
      send('Network.getResponseBody', { requestId: params.requestId }).then((res: any) => {
        if (res && typeof res.body === 'string') {
          const buf = res.base64Encoded ? Buffer.from(res.body, 'base64') : Buffer.from(res.body, 'utf-8')
          e.responseBody = capBody(buf, e.mime)
          put(e)
        }
      })
    } else if (method === 'Network.loadingFailed') {
      const e = cdpReq.get(params.requestId)
      if (e) {
        e.error = String(params?.errorText || 'failed')
        e.endedAt = Date.now()
      }
    } else if (method === 'Network.webSocketCreated') {
      recordWsCreated(params, wcId)
    } else if (method === 'Network.webSocketWillSendHandshakeRequest') {
      const c = wsConnections.get(`${wcId}:${params.requestId}`)
      if (c) c.requestHeaders = toHeaders(params?.request?.headers)
    } else if (method === 'Network.webSocketHandshakeResponseReceived') {
      const c = wsConnections.get(`${wcId}:${params.requestId}`)
      if (c) {
        c.responseHeaders = toHeaders(params?.response?.headers)
        c.status = 'open'
      }
    } else if (method === 'Network.webSocketFrameSent') {
      recordWsFrame(`${wcId}:${params.requestId}`, 'sent', params)
    } else if (method === 'Network.webSocketFrameReceived') {
      recordWsFrame(`${wcId}:${params.requestId}`, 'received', params)
    } else if (method === 'Network.webSocketClosed') {
      const c = wsConnections.get(`${wcId}:${params.requestId}`)
      if (c) c.status = 'closed'
    }
  }

  const onDetach = (): void => {
    deepAttached.delete(wcId)
  }
  dbg.on('detach', onDetach)
  guest.once('destroyed', () => {
    try {
      if (dbg.isAttached()) dbg.detach()
    } catch {
      /* noop */
    }
    onDetach()
    unmapTab(wcId)
  })
}

function recordWsCreated(params: any, wcId: number): void {
  const url = params?.url || ''
  const id = `${wcId}:${params.requestId}`
  const { host } = splitUrl(url)
  const c: WsConnection = {
    id,
    url,
    host,
    tabId: tabByWc.get(wcId) ?? null,
    createdAt: Date.now(),
    status: 'open',
    requestHeaders: [],
    responseHeaders: [],
    messages: [],
    inScope: isInScope(url)
  }
  if (!wsConnections.has(id)) {
    wsOrder.push(id)
    while (wsOrder.length > MAX_WS_CONNECTIONS) {
      const old = wsOrder.shift()
      if (old) wsConnections.delete(old)
    }
  }
  wsConnections.set(id, c)
}
function recordWsFrame(connId: string, direction: 'sent' | 'received', params: any): void {
  const c = wsConnections.get(connId)
  if (!c) return
  const payload = String(params?.response?.payloadData || '')
  const truncated = payload.length > MAX_BODY_BYTES
  c.messages.push({
    ts: Date.now(),
    direction,
    opcode: Number(params?.response?.opcode || 1),
    text: truncated ? payload.slice(0, MAX_BODY_BYTES) : payload,
    size: payload.length,
    truncated
  })
  if (c.messages.length > MAX_WS_MESSAGES) c.messages.shift()
}

// ── Query API (History) ──────────────────────────────────────────────────────
export interface HistoryFilter {
  search?: string
  host?: string
  method?: string
  status?: string // '2xx' | '3xx' | '4xx' | '5xx' | exact code
  type?: string
  tabId?: string
  inScopeOnly?: boolean
  limit?: number
  offset?: number
}
function matchFilter(e: Entry, f: HistoryFilter): boolean {
  if (f.inScopeOnly && !e.inScope) return false
  if (f.host && !e.host.toLowerCase().includes(f.host.toLowerCase())) return false
  if (f.method && e.method !== f.method.toUpperCase()) return false
  if (f.tabId && e.tabId !== f.tabId) return false
  if (f.type && !e.resourceType.toLowerCase().includes(f.type.toLowerCase()) && !e.mime.toLowerCase().includes(f.type.toLowerCase())) return false
  if (f.status) {
    if (/^[1-5]xx$/i.test(f.status)) {
      if (!e.status || Math.floor(e.status / 100) !== parseInt(f.status[0], 10)) return false
    } else if (String(e.status || '') !== f.status) return false
  }
  if (f.search) {
    const s = f.search.toLowerCase()
    if (!(e.url.toLowerCase().includes(s) || e.method.toLowerCase().includes(s) || e.mime.toLowerCase().includes(s))) return false
  }
  return true
}
function summary(e: Entry): object {
  return {
    id: e.id,
    ts: e.createdAt,
    method: e.method,
    host: e.host,
    path: e.path,
    url: e.url,
    status: e.status,
    mime: e.mime,
    resourceType: e.resourceType,
    requestSize: e.requestSize,
    responseSize: e.responseSize,
    durationMs: e.durationMs,
    tabId: e.tabId,
    inScope: e.inScope,
    protectedAuth: e.protectedAuth,
    error: e.error,
    hasResponseBody: e.responseBody.present
  }
}
export function getHistory(f: HistoryFilter = {}): { total: number; count: number; entries: object[]; stats: object } {
  const limit = Math.min(Math.max(f.limit ?? 200, 1), 500)
  const offset = Math.max(f.offset ?? 0, 0)
  const matched: Entry[] = []
  for (let i = order.length - 1; i >= 0; i--) {
    const e = entries.get(order[i])
    if (e && matchFilter(e, f)) matched.push(e)
  }
  const page = matched.slice(offset, offset + limit)
  return {
    total: matched.length,
    count: page.length,
    entries: page.map(summary),
    stats: { retained: order.length, cap: MAX_ENTRIES, approxBytes: totalBytes, ttlMs: ENTRY_TTL_MS }
  }
}
export function getEntry(id: string, opts: { reveal?: boolean } = {}): object | null {
  const e = entries.get(id)
  if (!e) return null
  const reveal = !!opts.reveal
  const parsedQuery: Array<{ name: string; value: string }> = []
  try {
    for (const [k, v] of new URLSearchParams(e.query)) parsedQuery.push({ name: k, value: v })
  } catch {
    /* noop */
  }
  return {
    ...summary(e),
    request: {
      headers: redactHeaders(e.requestHeaders, reveal),
      query: parsedQuery,
      body: redactBody(e.requestBody, reveal)
    },
    response: {
      statusText: e.statusText,
      headers: redactHeaders(e.responseHeaders, reveal),
      body: redactBody(e.responseBody, reveal)
    },
    redirectChain: e.redirectChain,
    producer: e.producer
  }
}

// ── Site Map / endpoint inventory ────────────────────────────────────────────
export function getSiteMap(opts: { inScopeOnly?: boolean } = {}): object {
  interface Node {
    host: string
    endpoints: Map<string, { path: string; methods: Set<string>; statuses: Set<number>; types: Set<string>; params: Set<string>; count: number; firstSeen: number; lastSeen: number; inScope: boolean }>
  }
  const hosts = new Map<string, Node>()
  for (const id of order) {
    const e = entries.get(id)
    if (!e || !e.host) continue
    if (opts.inScopeOnly && !e.inScope) continue
    let node = hosts.get(e.host)
    if (!node) {
      node = { host: e.host, endpoints: new Map() }
      hosts.set(e.host, node)
    }
    // normalize numeric/uuid path segments into {id} to keep the inventory compact
    const normPath = e.path.replace(/\/(\d+|[0-9a-f]{8}-[0-9a-f-]{27,})(?=\/|$)/gi, '/{id}') || '/'
    let ep = node.endpoints.get(normPath)
    if (!ep) {
      ep = { path: normPath, methods: new Set(), statuses: new Set(), types: new Set(), params: new Set(), count: 0, firstSeen: e.createdAt, lastSeen: e.createdAt, inScope: e.inScope }
      node.endpoints.set(normPath, ep)
    }
    ep.methods.add(e.method)
    if (e.status) ep.statuses.add(e.status)
    if (e.mime) ep.types.add(e.mime)
    ep.count++
    ep.lastSeen = e.createdAt
    try {
      for (const [k] of new URLSearchParams(e.query)) ep.params.add(k)
    } catch {
      /* noop */
    }
  }
  const out = [...hosts.values()]
    .map((n) => ({
      host: n.host,
      endpoints: [...n.endpoints.values()]
        .sort((a, b) => a.path.localeCompare(b.path))
        .map((ep) => ({
          path: ep.path,
          methods: [...ep.methods],
          statuses: [...ep.statuses],
          types: [...ep.types],
          params: [...ep.params],
          count: ep.count,
          firstSeen: ep.firstSeen,
          lastSeen: ep.lastSeen,
          inScope: ep.inScope
        }))
    }))
    .sort((a, b) => a.host.localeCompare(b.host))
  return { hosts: out, hostCount: out.length }
}

// ── WebSocket query ──────────────────────────────────────────────────────────
export function getWebSockets(): object {
  return {
    connections: [...wsConnections.values()].map((c) => ({
      id: c.id,
      url: c.url,
      host: c.host,
      tabId: c.tabId,
      status: c.status,
      messageCount: c.messages.length,
      createdAt: c.createdAt,
      inScope: c.inScope
    }))
  }
}
export function getWebSocketMessages(id: string, opts: { reveal?: boolean } = {}): object | null {
  const c = wsConnections.get(id)
  if (!c) return null
  return {
    id: c.id,
    url: c.url,
    status: c.status,
    requestHeaders: redactHeaders(c.requestHeaders, !!opts.reveal),
    responseHeaders: redactHeaders(c.responseHeaders, !!opts.reveal),
    messages: c.messages.slice(-MAX_WS_MESSAGES)
  }
}
